const properties = $input.item.json.body.shortlist || [];

let html = `<h1>Your Property Shortlist</h1>`;
html += `<table border="1" cellpadding="10" style="border-collapse: collapse;">`;
html += `<tr><th>Property ID</th><th>Society</th><th>Rent</th><th>BHK</th><th>SqFt</th></tr>`;

for (const p of properties) {
  html += `<tr>`;
  html += `<td>${p.id || 'N/A'}</td>`;
  html += `<td>${p.society || 'N/A'}</td>`;
  html += `<td>₹${p.rent_amount || 'N/A'}</td>`;
  html += `<td>${p.bhk || 'N/A'}</td>`;
  html += `<td>${p.sqft || 'N/A'}</td>`;
  html += `</tr>`;
}
html += `</table>`;

return { json: { html: html, email: $input.item.json.body.email || 'user@example.com' } };
